typedef float rational_t;

extern "C" float sqrtf(float);
extern "C" float fabsf(float);

class vector3d
{
public:
  rational_t x, y, z;

  inline vector3d() {}
  inline vector3d(const vector3d& v) { x = v.x; y = v.y; z = v.z; }
  inline vector3d(rational_t _x, rational_t _y, rational_t _z) { x = _x; y = _y; z = _z; }

  inline rational_t length2() const
  { return x*x + y*y + z*z; }

  inline rational_t length() const
  { return (rational_t)sqrtf(x*x + y*y + z*z); }
};

inline vector3d operator - (const vector3d& a, const vector3d& b)
{ return vector3d(a.x - b.x, a.y - b.y, a.z - b.z); }

bool crossed_point(const vector3d test_point, const vector3d &cur_pos, const vector3d &last_pos, rational_t radius, bool force_xz)
{
    vector3d delta = ( test_point - cur_pos );
    vector3d test_delta = ( test_point - last_pos );
    vector3d move = (cur_pos - last_pos);
    rational_t test_len = 0.0f;

    if ( force_xz || fabsf(delta.y) < 1.0f )
    {
      delta.y = 0.0f;
      test_delta.y = 0.0f;
      move.y = 0.0f;
    }

    return(delta.length2() <= radius*radius || (test_len = test_delta.length() - radius) <= 0.0f || move.length2() >= test_len*test_len );
}
